}","keccak256":"0xea9c996c2246f9f1072e716bf8bc99ade2511bde8bf88ed9b03d203b9981de36","license":"None"},"SuperChamps/interfaces/ISCMetagameRegistry.sol":{"content":"// SPDX-License-Identifier: None
