// Super Champs Foundation 2024

pragma solidity ^0.8.24;

import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import "../../interfaces/IPermissionsManager.sol";
import "../../interfaces/IERC721MetadataRenderer.sol";

/// @title Single entry (semi-fungible style) Soul Bound Token metadata renderer. 
/// @author Chance Santana-Wees (Coelacanth/Coel.eth)
/// @dev Conforms to subset of IERC721Metadata. Able to be replaced by a custom on-chain SVG renderer.
contract SCGenericRenderer is IERC721MetadataRenderer {
    using Strings for uint256;

    ///@notice The permissions registry
    IPermissionsManager private immutable _permissions;

    ///@notice The name which is returned by the name() function.
    string _name;

    ///@notice The symbol which is returned by the symbol() function.
    string _symbol;

    ///@notice The name which is returned by the name() function.
    string _uri;

    ///@notice Toggle that switches to render using concatenated token IDs.
    bool _concatenate_ids = true;

    ///@notice A function modifier that restrics calls to addresses with the Systems Admin permission set.
    modifier isSystemsAdmin() {
        require(_permissions.hasRole(IPermissionsManager.Role.SYSTEMS_ADMIN, msg.sender));
        _;
    }

    ///@param permissions_ The protocol permissions registry
    ///@param name_ The name of the NFT collection associated with this renderer.
    ///@param symbol_ The symbol of the NFT collection associated with this renderer.
    constructor(
        IPermissionsManager permissions_,
        string memory name_, 
        string memory symbol_,
        string memory uri_) 
    {
        _permissions = permissions_;
        _name = name_;
        _symbol = symbol_;
        _uri = uri_;
    }    

    ///@notice Sets the URI to return from the tokenURI() function.
    ///@dev Only callable by a Systems Admin.
    ///@param uri_ The new URI to return.
    ///@param concatenate_ids_ Whether or not to concatenate token IDs to the end of the base uri_
    function setURI(string memory uri_, bool concatenate_ids_) external isSystemsAdmin {
        _uri = uri_;
        _concatenate_ids = concatenate_ids_;
    }

    /**
     * @dev See {IERC721Metadata-name}.
     */
    function name() public view override returns (string memory) {
        return _name;
    }

    /**
     * @dev See {IERC721Metadata-symbol}.
     */
    function symbol() public view override returns (string memory) {
        return _symbol;
    }

    /**
     * @dev See {IERC721Metadata-tokenURI}.
     */
    function tokenURI(uint256 token_id_) public view override returns (string memory _uri_) {
        if(_concatenate_ids) 
        {
            if(bytes(_uri).length > 0) {
                return string.concat(_uri, token_id_.toString());
            } else {
                return "";
            }
        } 
        else 
        {
            return _uri;
        }
    }

    /**
     * @dev See {IERC721Metadata-tokenURI}.
     */
    function tokenURI(uint256[] memory token_id_elements_) public view returns (string memory _uri_) {
        if(_concatenate_ids) 
        {
            if(bytes(_uri).length > 0) {
                _uri_ = _uri;
                for(uint256 i = 0; i < token_id_elements_.length; i++) {
                    _uri_ = string.concat(_uri_,"/",token_id_elements_[i].toString());
                }
            } else {
                _uri_ = "";
            }
        } 
        else 
        {
            return _uri;
        }
    }
}","keccak256":"0x1e6260d1d501e2dc4614c8751fc046fa899170e5316c270758503c99b44880c7","license":"None"},"SuperChamps/interfaces/IERC721MetadataRenderer.sol":{"content":"// SPDX-License-Identifier: None
// Super Champs Foundation 2024

pragma solidity ^0.8.0;

/**
 * @title Subset of ERC-721 Non-Fungible Token Standard, optional metadata extension
 * @dev See https://eips.ethereum.org/EIPS/eip-721
 */
interface IERC721MetadataRenderer {
    /**
     * @dev Returns the token collection name.
     */
    function name() external view returns (string memory);

    /**
     * @dev Returns the token collection symbol.
     */
    function symbol() external view returns (string memory);

    /**
     * @dev Returns the Uniform Resource Identifier (URI) for `tokenId` token.
     */
    function tokenURI(uint256 tokenId) external view returns (string memory);

    /**
     * @dev Returns the Uniform Resource Identifier (URI) for a token with multiple identifying elements.
     */
    function tokenURI(uint256[] memory token_id_elements_) external view returns (string memory);
}","keccak256":"0xeaaff65a4e14247b227e9bc659d6eb2095583f2c2fc347baf464cfefd42822e5","license":"None"},"SuperChamps/interfaces/IPermissionsManager.sol":{"content":"// SPDX-License-Identifier: None
// Super Champs Foundation 2024

pragma solidity ^0.8.24;

/// @title Interface for protocol permissions registry
/// @author Chance Santana-Wees (Coelacanth/Coel.eth)
interface IPermissionsManager{
    ///@notice All available roles.
    ///@dev EXT roles are available for future application.
    enum Role {
        ANY,
        GLOBAL_ADMIN,
        MINT_ADMIN,
        TRANSFER_ADMIN,
        SYSTEMS_ADMIN,
        EXT1,
        EXT2,
        EXT3,
        EXT4,
        EXT5,
        EXT6,
        EXT7,
        EXT8,
        EXT9,
        EXT10
    }

    /**
    * @param role_ ISCPermissionsManager.Role to query
    * @param account_ Address to check for role_
    */
    function hasRole(Role role_, address account_) external view returns(bool);

    /**
    * @param role_ ISCPermissionsManager.Role to add
    * @param account_ Address to add role_ on
    */
    function addRole(Role role_, address account_) external;

    /**
    * @param role_ ISCPermissionsManager.Role to remove
    * @param account_ Address to remove role_ from
    */
    function removeRole(Role role_, address account_) external;
}","keccak256":"0x6d1c791929fc493f761e3ee4f4e66dbdb398ba3817c0a5ed6d3fc2ba7a62ef52","license":"None"}},"version":1}

