// Super Champs Foundation 2024

pragma solidity ^0.8.24;

/// @title Interface for protocol permissions registry
/// @author Chance Santana-Wees (Coelacanth/Coel.eth)
interface IPermissionsManager{
    ///@notice All available roles.
    ///@dev EXT roles are available for future application.
    enum Role {
        ANY,
        GLOBAL_ADMIN,
        MINT_ADMIN,
        TRANSFER_ADMIN,
        SYSTEMS_ADMIN,
        EXT1,
        EXT2,
        EXT3,
        EXT4,
        EXT5,
        EXT6,
        EXT7,
        EXT8,
        EXT9,
        EXT10
    }

    /**
    * @param role_ ISCPermissionsManager.Role to query
    * @param account_ Address to check for role_
    */
    function hasRole(Role role_, address account_) external view returns(bool);

    /**
    * @param role_ ISCPermissionsManager.Role to add
    * @param account_ Address to add role_ on
    */
    function addRole(Role role_, address account_) external;

    /**
    * @param role_ ISCPermissionsManager.Role to remove
    * @param account_ Address to remove role_ from
    */
    function removeRole(Role role_, address account_) external;
}","keccak256":"0x6d1c791929fc493f761e3ee4f4e66dbdb398ba3817c0a5ed6d3fc2ba7a62ef52","license":"None"},"SuperChamps/interfaces/ISCSeasonRewards.sol":{"content":"// SPDX-License-Identifier: None
// Super Champs Foundation 2024

pragma solidity ^0.8.24;

/// @title Interface for protocol's seasonal player rewards program
/// @author Chance Santana-Wees (Coelacanth/Coel.eth)
interface ISCSeasonRewards {
    struct Season {
        uint256 id;
        uint256 start_time;
        uint256 end_time;
        uint256 reward_amount;
        uint256 remaining_reward_amount;
        uint256 claim_end_time;   //Last time claim is available
    }

    function startSeason(
        uint256 start_time_
    ) external returns(Season memory);

    function endSeason(
        uint256 id_
    ) external;

    function finalize(
        uint256 id_,
        uint256 reward_amount_,
        uint256 claim_duration
    ) external;

    function reportRewards(
        uint256 season_id_,
        address[] calldata players_,
        uint256[] calldata rewards_
    ) external;

    function claimReward(
        uint256 season_id_
    ) external;

    function getClaimableReward(
        uint256 season_id_
    ) external view returns(uint256); 

    function revokeUnclaimedReward(
        uint256 id_
    ) external;
}","keccak256":"0x3bf1a6cbdbbcf7fdf057ffb48f6f6a143d9294ecee2c9acf10fa20251bc4bf77","license":"None"}},"version":1}

